window.LD=window.LD||{};window.LD["party/p6"]={"id":"p6","name":"Gilded Wall","poss":"Gilded Wall's","members":["h9","h6"],"leader":"h9","morale":94,"disposition":"honorable","motto":"Swear it, keep it.","banner":{"c1":"#e8c83a","c2":"#4caf50","emblem":"shield"},"loc":"whitepeak","loc_name":"Whitepeak Pass","goal":{"text":"to finish the season as one of the top three parties","kind":"top","done":null,"progress":"finished 5th","missed":true,"crew":"Gilded Wall","party":"p6"},"vows":[{"text":"never to leave a companion behind","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"Gilded Wall","party":"p6"}],"doing":"last seen delving into Frostspire","progress":null,"today":["Ate 2 rations."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"brynjars_horn","title":"Blow the Horn, Brynjar","tone":"heroic","meter":"3/4","bpm":99,"diff":2,"day":28,"night":"n74","n":6,"by":null,"lead":{"id":"h6","name":"Tobias","skill":0.468,"inst":"drum"}},"renown":150,"season":{"wins":7,"bosses":0,"floors":2,"gold":0,"deaths":0,"fled":2,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30},"career":{"wins":21,"bosses":0,"floors":8,"gold":0,"deaths":0,"fled":2,"pvp_wins":0,"pvp_losses":1,"renown":0,"days":90},"former":[],"fallen":[],"travel":null,"wagon":null,"pace_gap":12,"rels":[{"party":"p3","score":-100},{"party":"p4","score":100},{"party":"p7","score":46},{"party":"p8","score":35},{"party":"p5","score":31},{"party":"p2","score":25},{"party":"p1","score":9}],"events":[{"id":"e31","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Gorm and Tobias shake on it at The Pickaxe & Pint: they are now Gilded Wall. (Honorable, by the look of them.)","heroes":["h9","h6"],"parties":["p6"],"loc":"veldrock"},{"id":"e749","day":20,"season":1,"sday":20,"kind":"road","imp":2,"text":"Tobias nurses a hawk on the road to Bleakmarsh for an hour. It flies in a perfect circle overhead, drops a feather at their feet and is gone.","heroes":["h6","h9"],"parties":["p6"],"road":"bleakmarsh~carrbridge","road_rec":"r181"},{"id":"e758","day":20,"season":1,"sday":20,"kind":"bond","imp":2,"text":"Gilded Wall and Verdant Edge are rivals now, starting with Tobias and Ash.","heroes":["h6","h12"],"parties":["p6","p8"],"bond":"rivals"},{"id":"e759","day":20,"season":1,"sday":20,"kind":"rescue","imp":4,"text":"Verdant Edge is in a bad way in Bleakmarsh when Gilded Wall turns up. Gorm (Lee's hero) gets Fenwick (Quinn's hero) on a horse. A debt is remembered.","heroes":["h9","h17","h6","h12"],"parties":["p6","p8"],"loc":"bleakmarsh","rescuers":["h9","h6"]},{"id":"e770","day":20,"season":1,"sday":20,"kind":"meet","imp":1,"text":"Verdant Edge and Gilded Wall need the same stream in Bleakmarsh and take turns at it without a word, each side watching the other's hands.","heroes":["h12","h17","h9","h6"],"parties":["p8","p6"],"loc":"bleakmarsh"},{"id":"e807","day":21,"season":1,"sday":21,"kind":"meet","imp":1,"text":"The Sunlit Almanac and Gilded Wall share a fire at the mouth of Thornmere Ruins. There is a short argument about the best road to Ironhaven.","heroes":["h8","h20","h18","h19","h9","h6"],"parties":["p4","p6"],"loc":"thornmere_ruins"},{"id":"e830","day":22,"season":1,"sday":22,"kind":"delve","imp":1,"text":"Gilded Wall descends into Thornmere Ruins, barely touched (6%).","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e833","day":22,"season":1,"sday":22,"kind":"fight","imp":2,"text":"Tobias hits hardest as Gilded Wall handles 2 Sirens and a Swamp Troll in the reed stair on the first floor of Thornmere Ruins. The swamp troll went down to Tobias' Game Shot. Loot: 21 silver each, 1 gem, 2 trinkets.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f57","foes":["siren","siren","swamp_troll"],"where":"in the reed stair on the first floor of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-23,"wx":"fog"},{"id":"e834","day":22,"season":1,"sday":22,"kind":"delve_day","imp":1,"text":"Six rooms on the first floor of Thornmere Ruins for Gilded Wall today: the reed beds, the smugglers' dry stair, the porters' lodge and 3 more.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":6,"empty":4,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":1,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e864","day":22,"season":1,"sday":22,"kind":"talent","imp":2,"text":"Gorm sorts the crew's gear by who dented it, and sends each of them the bill in knuckle-taps. Hammer and Hold: one of the things Gorm learned the long way round.","heroes":["h9"],"parties":["p6"],"loc":"thornmere_ruins","skill":"hammer_and_hold","wx":"fog"},{"id":"e892","day":23,"season":1,"sday":23,"kind":"delve_day","imp":1,"text":"Gilded Wall works the first floor of Thornmere Ruins one door at a time: six rooms (the temple fish ponds, the drowned nave, the flooded side aisle and 3 more).","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":6,"empty":6,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e901","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Tobias gives a short, fierce speech at the top of the stairs at Thornmere Ruins. The crew goes down with chins up. Speechmaker, minus the shouting.","heroes":["h6"],"parties":["p6"],"loc":"thornmere_ruins","skill":"speechmaker","wx":"fog"},{"id":"e910","day":24,"season":1,"sday":24,"kind":"fight","imp":2,"text":"Gilded Wall meets a Swamp Troll in the refectory on the first floor of Thornmere Ruins and beats it. Gorm ended it with Anvil Drop. Loot: 32 silver each, 2 troll hide, 2 herbs.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f62","foes":["swamp_troll"],"where":"in the refectory on the first floor of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-13,"wx":"fog"},{"id":"e911","day":24,"season":1,"sday":24,"kind":"delve_day","imp":1,"text":"The sunken stair behind the font, the reliquary niche, the refectory: the day's work on the first floor of Thornmere Ruins for Gilded Wall, taken at speed.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"empty":1,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e912","day":24,"season":1,"sday":24,"kind":"talent","imp":1,"text":"Tobias turns a hare on a green stick over the coals and hands out the crispy bits first. (Back by Supper, if anyone's asking.)","heroes":["h6"],"parties":["p6"],"loc":"thornmere_ruins","skill":"back_by_supper","wx":"fog"},{"id":"e947","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"A long day on the second floor of Thornmere Ruins. Gilded Wall comes through three rooms, at a steady pace: the priests' cells, a sealed space off the priests' cells, the font that still fills.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"empty":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e974","day":25,"season":1,"sday":25,"kind":"campfire","imp":2,"text":"Gorm carries Tobias's pack for the last mile without being asked.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e982","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"The map of Thornmere Ruins grows by four rooms of the second floor, walked carefully by Gilded Wall: the confession box, the granary, the granary and 1 more.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":4,"empty":3,"size":2,"floor":2,"traps":1,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1029","day":27,"season":1,"sday":27,"kind":"trap","imp":3,"text":"Gorm springs a sinkhole under green scum in the eel-traps on the second floor of Thornmere Ruins (bruised ribs).","heroes":["h9"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1030","day":27,"season":1,"sday":27,"kind":"delve_day","imp":1,"text":"Deeper into the second floor of Thornmere Ruins: Gilded Wall sees four rooms today, at a cautious pace (the reliquary niche, the curtain of hair, the illuminators' desks and 1 more).","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":4,"empty":3,"size":2,"floor":2,"traps":1,"sprung":1,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1031","day":27,"season":1,"sday":27,"kind":"night","imp":2,"text":"A tinker trades Gilded Wall's camp on the second floor of Thornmere Ruins a kettle for a story, then tells one back: something under Emberdeep is still awake.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1053","day":28,"season":1,"sday":28,"kind":"party_life","imp":3,"text":"The second floor of Thornmere Ruins had the last word with Gorm, and Gilded Wall turns up the stairs while it still seemed polite.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","refusal":"h9","wx":"fog"},{"id":"e1054","day":28,"season":1,"sday":28,"kind":"delve_done","imp":1,"text":"After 7 days underground, Gilded Wall climbs back into the open air, gulping it down like water. They worked through 7 rooms, got down to the second floor, inked 46% of the map, turned up The Lantern That Waits, came away with 106 silver between them and turned back when one of them would go no further. Thornmere Ruins is partly explored (40%) now, with the league's pencil marks all over it.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","days":7,"bottom":false,"rooms":["The Lantern That Waits"],"gold":106,"turn":"refused","wx":"fog"},{"id":"e1055","day":28,"season":1,"sday":28,"kind":"night","imp":1,"text":"Something small and clever gets into Gilded Wall's camp outside Thornmere Ruins overnight. Tobias wakes up 2 silver and 1 ration lighter.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1081","day":28,"season":1,"sday":28,"kind":"music","imp":3,"text":"Gilded Wall sang \"Blow the Horn, Brynjar\" under a clear sky last night, and somewhere in the chorus it became their anthem. Ask any of them; they'll sing it for you.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","anthem":"brynjars_horn","night":"n74","wx":"fog"},{"id":"e1085","day":28,"season":1,"sday":28,"kind":"ledger","imp":2,"text":"The week's trade: 7 packs emptied onto counters for 265 silver. Biggest haul: Ash, 89 silver in Carrbridge. Back up from the deep: Red Hammers (2 days in the Ashveil Crypts), Gilded Wall (7 days in Thornmere Ruins).","heroes":["h12","h13","h9"],"parties":["p1","p6"]},{"id":"e1089","day":29,"season":1,"sday":29,"kind":"road","imp":2,"text":"The wagon at Wetfoot Ford comes free and Tobias goes under. The driver pulls her out by the collar and laughs until crying.","heroes":["h6","h9"],"parties":["p6"],"road":"bleakmarsh~thornmere_ruins","road_rec":"r243"},{"id":"e1181","day":30,"season":1,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and Gilded Wall came up short: finish the season as one of the top three parties (finished 6th).","heroes":["h9","h6"],"parties":["p6"]},{"id":"e1202","day":31,"season":2,"sday":1,"kind":"road","imp":3,"text":"Brother Aldo is too ill to walk, so Tobias shoulders the pack and most of the pilgrim as far as the next shelter.","heroes":["h6","h9"],"parties":["p6"],"road":"ironhaven~thornwall","traveller":"aldo","road_rec":"r256"},{"id":"e1243","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Gorm and Tobias see in a month of Gilded Wall by splitting the last good bottle. Nobody else is offered any.","heroes":["h9","h6"],"parties":["p6"],"loc":"ironhaven"},{"id":"e1252","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from Gilded Wall: never to leave a companion behind. Easy to say on day one.","heroes":["h9","h6"],"parties":["p6"]},{"id":"e1265","day":32,"season":2,"sday":2,"kind":"road","imp":2,"text":"Gorm reaches into a gap in the broken watchtower wall and pulls out a tin of 4 silver, still sealed with tallow.","heroes":["h9","h6"],"parties":["p6"],"road":"ironhaven~redcrag","road_rec":"r274"},{"id":"e1275","day":32,"season":2,"sday":2,"kind":"meet","imp":1,"text":"Gilded Wall and The Scarlet Gallopers share a fire in Redcrag Hills and trade news.","heroes":["h9","h6","h4","h15","h5"],"parties":["p6","p5"],"loc":"redcrag"},{"id":"e1280","day":32,"season":2,"sday":2,"kind":"ability","imp":2,"text":"On the way to Redcrag Hills, Tobias reads a muddy wallow like a letter, follows it into the oaks and comes out an hour later carrying a boar shoulder.","heroes":["h6"],"parties":["p6"],"loc":"redcrag","skill":"back_by_supper","sk":"Back by Supper","rule":true},{"id":"e1312","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Gorm hammers a bent greave straight on a milestone near Redcrag Hills. The milestone is now a little flatter.","heroes":["h9"],"parties":["p6"],"loc":"redcrag","skill":"hammer_and_hold"},{"id":"e1357","day":34,"season":2,"sday":4,"kind":"campfire","imp":1,"text":"Gorm admits to being afraid of the dead. Tobias doesn't laugh. Tobias just nods and takes the watch nearest it.","heroes":["h6","h9"],"parties":["p6"],"loc":"redcrag"},{"id":"e1365","day":35,"season":2,"sday":5,"kind":"fight","imp":1,"text":"In Redcrag Hills, 3 Kobolds get in Gilded Wall's way, briefly. Gorm stepped in with Hammer Down, and the kobold was on the ground. Tobias's Ambush kicked in when it counted. Loot: 8 silver each, a kobold firepepper, 1 ore.","heroes":["h9","h6"],"parties":["p6"],"loc":"redcrag","fight":"f80","foes":["kobold","kobold","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"place","reworded":-3},{"id":"e1411","day":36,"season":2,"sday":6,"kind":"talent","imp":2,"text":"Gorm refuses to drink until Tobias's breastplate is back to shape. Tobias is touched and slightly embarrassed.","heroes":["h9","h6"],"parties":["p6"],"loc":"veldrock","skill":"hammer_and_hold"},{"id":"e1492","day":38,"season":2,"sday":8,"kind":"road","imp":3,"text":"'This is Corporal Nobody,' says Sergeant Hobb Withy, and Gorm salutes him. 'Good. He likes you.'","heroes":["h9","h6"],"parties":["p6"],"road":"carrbridge~ironhaven","traveller":"withy","road_rec":"r306"},{"id":"e1547","day":39,"season":2,"sday":9,"kind":"meet","imp":2,"text":"The Sunlit Almanac meets Gilded Wall on the road between Bleakmarsh and Carrbridge, and for one evening the talk is all roads, prices and who owes whom.","heroes":["h8","h20","h18","h19","h9","h6"],"parties":["p4","p6"],"loc":"bleakmarsh"},{"id":"e1564","day":40,"season":2,"sday":10,"kind":"night","imp":2,"text":"Tobias's ghost story in Thornmere Ruins ends with \"...and it was standing right behind them.\" Gorm does not look behind her once, all night.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins"},{"id":"e1589","day":40,"season":2,"sday":10,"kind":"map_shared","imp":1,"text":"The Vigil of Carrbridge draws Gilded Wall a rough copy of Thornmere Ruins on the back of a ration wrapper, as far as the deepest floor. Friends do that.","heroes":["h10","h1","h9","h6"],"parties":["p2","p6"],"loc":"bleakmarsh","dungeon":"thornmere_ruins","price":0},{"id":"e1590","day":40,"season":2,"sday":10,"kind":"meet","imp":2,"text":"Gilded Wall and The Vigil of Carrbridge pass on the road between Bleakmarsh and Thornmere Ruins and split the last of somebody's bread. The news goes round twice.","heroes":["h9","h6","h10","h1"],"parties":["p6","p2"],"loc":"bleakmarsh"},{"id":"e1619","day":41,"season":2,"sday":11,"kind":"delve","imp":1,"text":"Gilded Wall descends into Thornmere Ruins, mostly explored (69%), map in hand.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins"},{"id":"e1620","day":41,"season":2,"sday":11,"kind":"fight","imp":1,"text":"It's 2 Bog Crawlers against Gilded Wall in the gatehouse yard on the first floor of Thornmere Ruins, and it isn't close. It was even until Gorm's Hammer Down. Then it wasn't. Loot: 10 chitin, 2 bog crawler claws.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f94","foes":["bog_crawler","bog_crawler"],"where":"in the gatehouse yard on the first floor of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-25},{"id":"e1621","day":41,"season":2,"sday":11,"kind":"delve_day","imp":1,"text":"Gilded Wall tallies up the first floor of Thornmere Ruins at nightfall: two rooms, taken one door at a time, and the names go in the book (the gatehouse yard, the scriptorium).","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1622","day":41,"season":2,"sday":11,"kind":"ambush","imp":2,"text":"Gilded Wall, in fine spirits lately, makes short work of a Bog Crawler and a Will-o'-Wisp at their camp on the first floor of Thornmere Ruins, in the middle of the night. The last will-o'-wisp slips away while nobody is looking. Tobias loosed Game Shot, and the bog crawler dropped. Ambush came over Tobias at the right moment, as it does. Loot: 2 bog crawler claws.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f95","foes":["bog_crawler","wisp"],"where":"at their camp on the first floor of Thornmere Ruins, in the middle of the night","won":true,"close":false,"shape":"mood","reworded":-54},{"id":"e1653","day":41,"season":2,"sday":11,"kind":"goal","imp":1,"text":"Gilded Wall's plan for the season, as told to the barkeep: to find a relic of the old world.","heroes":["h9","h6"],"parties":["p6"]},{"id":"e1666","day":42,"season":2,"sday":12,"kind":"wild_room","imp":3,"text":"Tobias caught a wisp in a game of tag in Thornmere Ruins and the whole hall of them lay down, as pleased as lights can be. The wisp is said to be 'it.'","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","room":"wild_wisp_tag"},{"id":"e1667","day":42,"season":2,"sday":12,"kind":"delve_day","imp":1,"text":"Gilded Wall keeps at the first floor of Thornmere Ruins at a cautious pace, two rooms deep in the day: the buttery, the wisps' game of tag.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_wisp_tag"]}},{"id":"e1668","day":42,"season":2,"sday":12,"kind":"ambush","imp":2,"text":"Gilded Wall wakes to a Will-o'-Wisp and a Bog Crawler in camp on the first floor of Thornmere Ruins in the middle of the night, and sees them off. That Game Shot from Tobias was the moment it tipped. Gorm finished it, quietly, while the others were still catching their breath. Loot: 2 bottled wisplight, 2 wisp sugar.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f97","foes":["wisp","bog_crawler"],"where":"at their camp on the first floor of Thornmere Ruins, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-12},{"id":"e1697","day":43,"season":2,"sday":13,"kind":"delve_day","imp":1,"text":"Torch by torch through the second floor of Thornmere Ruins, Gilded Wall makes it through two rooms, slowly, chalking every door: the bell tower, the cloister garth.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1716","day":43,"season":2,"sday":13,"kind":"talent","imp":2,"text":"Gorm tightens a loose strap on Tobias mid-corridor, without asking, without breaking stride. Chalk it up to Hammer and Hold.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","skill":"hammer_and_hold","wx":"rain"},{"id":"e1737","day":44,"season":2,"sday":14,"kind":"delve_day","imp":1,"text":"By lamplight on the deepest floor of Thornmere Ruins, Gilded Wall clears the way through six rooms, at speed: the chapel of the first abbot, the undercroft arches, the hag's still room and 3 more.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":6,"empty":6,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1738","day":44,"season":2,"sday":14,"kind":"talent","imp":1,"text":"Gorm tells a story round the fire that starts in a swamp and ends, somehow, at a wedding. Tobias asks for it again.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","skill":"tavern_tales","wx":"rain"},{"id":"e1769","day":45,"season":2,"sday":15,"kind":"fight","imp":3,"text":"With Tobias hitting hardest, Gilded Wall defeats 2 Bog Crawlers and a Siren in the pond banks on the deepest floor of Thornmere Ruins. The bog crawler had been trouble right up until Tobias' Bring It Down. Loot: 10 chitin, 2 bog crawler claws, 3 trinkets.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f100","foes":["bog_crawler","siren","bog_crawler"],"where":"in the pond banks on the deepest floor of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-29,"wx":"rain"},{"id":"e1770","day":45,"season":2,"sday":15,"kind":"delve_day","imp":1,"text":"Gilded Wall works the deepest floor of Thornmere Ruins at a hard pace: four rooms (the gallery of charms, the Hag Mother's nest, the drowned crypt and 1 more).","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":4,"empty":2,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"rain"},{"id":"e1794","day":46,"season":2,"sday":16,"kind":"fight","imp":3,"text":"Gilded Wall meets 3 Drakes in the undercroft arches on the deepest floor of Thornmere Ruins and dispatches them. The last drake doesn't stay to see the end. Ask anyone when it turned: Tobias' Bring It Down. Loot: 1 drake scale, 2 drake flanks.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","fight":"f102","foes":["drake","drake","drake"],"where":"in the undercroft arches on the deepest floor of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-37,"wx":"rain"},{"id":"e1795","day":46,"season":2,"sday":16,"kind":"delve_day","imp":1,"text":"Gilded Wall pushes on through the deepest floor of Thornmere Ruins carefully. Two rooms by nightfall: the cloister walk, the undercroft arches.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1809","day":46,"season":2,"sday":16,"kind":"campfire","imp":2,"text":"Tobias and Gorm find a pear tree by the road and eat far more than is wise.","heroes":["h6","h9"],"parties":["p6"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1817","day":47,"season":2,"sday":17,"kind":"delve_day","imp":1,"text":"Deeper into the deepest floor of Thornmere Ruins: Gilded Wall sees two rooms today, at a steady pace (the lantern rack, the chapel of the first abbot).","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e1818","day":47,"season":2,"sday":17,"kind":"delve_done","imp":3,"text":"Gilded Wall comes out after 7 days, and the first thing anyone wants is bread. They worked through 12 rooms, reached the deepest floor, found the buttery, the wisps' game of tag and the bell tower, mapped 97% of it, came away with 135 silver between them and turned back because they were down to the last torch. Add up every party's sketches and Thornmere Ruins comes out mostly explored (88%).","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","days":7,"bottom":true,"rooms":["the buttery","the wisps' game of tag"],"gold":135,"turn":"dark","wx":"fog"},{"id":"e1838","day":47,"season":2,"sday":17,"kind":"campfire","imp":3,"text":"Gorm and Tobias pick leeches off each other by firelight and score them by size.","heroes":["h9","h6"],"parties":["p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1865","day":48,"season":2,"sday":18,"kind":"talent","imp":1,"text":"Tobias leaves the road near Bleakmarsh for a deer track and comes back an hour later with supper over one shoulder. Chalk it up to Game Trails.","heroes":["h6"],"parties":["p6"],"loc":"bleakmarsh","skill":"game_trails","wx":"fog"},{"id":"e1866","day":48,"season":2,"sday":18,"kind":"ability","imp":2,"text":"Tobias hears rooting in the beechwood past Bleakmarsh, strings her bow without a word, and is home before the kettle with a boar shoulder.","heroes":["h6"],"parties":["p6"],"loc":"bleakmarsh","skill":"back_by_supper","sk":"Back by Supper","rule":true,"wx":"fog"},{"id":"e1923","day":50,"season":2,"sday":20,"kind":"road","imp":2,"text":"The Fourth-Best Company share the road with Tobias for the first time. Twice tells the story of their last job. It gets bigger every mile.","heroes":["h6","h9"],"parties":["p6"],"road":"ashfen~carrbridge","traveller":"fourth_best","road_rec":"r402"},{"id":"e1975","day":51,"season":2,"sday":21,"kind":"meet","imp":2,"text":"Gilded Wall meets Red Hammers on the road between Carrbridge and Ironhaven, and for one evening the talk is all roads, prices and who owes whom.","heroes":["h9","h6","h13","h14"],"parties":["p6","p1"],"loc":"carrbridge"},{"id":"e2008","day":52,"season":2,"sday":22,"kind":"ability","imp":2,"text":"Tobias trails a sounder of pigs along a stream outside Redcrag Hills till noon, takes one clean shot, and walks on with a boar shoulder slung from a pole.","heroes":["h6"],"parties":["p6"],"loc":"redcrag","skill":"back_by_supper","sk":"Back by Supper","rule":true},{"id":"e2026","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Gorm narrates the walk like an epic. Every stile becomes a mountain pass. The miles go quicker. Somebody asks how. 'Tavern Tales,' says Gorm.","heroes":["h9"],"parties":["p6"],"loc":"redcrag","skill":"tavern_tales"},{"id":"e2069","day":54,"season":2,"sday":24,"kind":"talent","imp":2,"text":"Gorm hands Tobias a cup at a roadside halt and doesn't ask what's wrong. Tobias says anyway.","heroes":["h9","h6"],"parties":["p6"],"loc":"redcrag","skill":"tea_ceremony"},{"id":"e2156","day":57,"season":2,"sday":27,"kind":"party_life","imp":1,"text":"By the third crossroads Tobias has stopped waiting and started complaining about the wait.","heroes":["h9","h6"],"parties":["p6"],"loc":"frosthold","wx":"snow"},{"id":"e2173","day":57,"season":2,"sday":27,"kind":"feud","imp":4,"text":"It's a feud: The Amber Sigil and Gilded Wall are sworn enemies, led by Quill and Gorm. (4 heroes now hold grudges.)","heroes":["h11","h9","h6","h16"],"parties":["p3","p6"],"bond":"nemeses"},{"id":"e2174","day":57,"season":2,"sday":27,"kind":"bond","imp":3,"text":"The Amber Sigil and Gilded Wall are rivals now, starting with Sela and Tobias.","heroes":["h2","h6"],"parties":["p3","p6"],"bond":"rivals"},{"id":"e2175","day":57,"season":2,"sday":27,"kind":"pvp","imp":5,"text":"The Amber Sigil flattens Gilded Wall on the road between Frosthold and Whitepeak Pass after a robbery goes wrong and walks off with 25 silver.","heroes":["h11","h2","h16","h9","h6"],"parties":["p3","p6"],"loc":"frosthold","fight":"f128","losers":["h9","h6"],"wx":"snow"},{"id":"e2194","day":58,"season":2,"sday":28,"kind":"party_life","imp":1,"text":"Gorm arrives at camp an hour behind Tobias and finds the good spot by the fire taken.","heroes":["h9","h6"],"parties":["p6"],"loc":"whitepeak","wx":"snow"},{"id":"e2195","day":58,"season":2,"sday":28,"kind":"road","imp":3,"text":"A cheese the size of a cartwheel comes rolling down the hill beside the road to Frosthold with half a village after it. Gorm stops it with a boot and a shout, and is carried to the village on shoulders.","heroes":["h9","h6"],"parties":["p6"],"road":"frosthold~whitepeak","road_rec":"r462"},{"id":"e2219","day":58,"season":2,"sday":28,"kind":"talent","imp":1,"text":"A Frosthold butcher takes a brace of rabbits off Tobias's hands and asks for more next week. Back by Supper all the way, Tobias insists.","heroes":["h6"],"parties":["p6"],"loc":"frosthold","skill":"back_by_supper","wx":"snow"},{"id":"e2301","day":60,"season":2,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and Gilded Wall came up short: find a relic of the old world (still looking).","heroes":["h9","h6"],"parties":["p6"]},{"id":"e2357","day":61,"season":3,"sday":1,"kind":"talent","imp":2,"text":"Tobias names every set of tracks crossing the road until Gorm begs her to stop. There are a lot of tracks.","heroes":["h6","h9"],"parties":["p6"],"loc":"veldrock","skill":"back_by_supper","wx":"storm"},{"id":"e2368","day":61,"season":3,"sday":1,"kind":"campfire","imp":1,"text":"Gorm reads aloud while Tobias sharpens blades, and neither wants the chapter to end.","heroes":["h9","h6"],"parties":["p6"],"loc":"veldrock","wx":"storm"},{"id":"e2377","day":62,"season":3,"sday":2,"kind":"road","imp":4,"text":"At the last shrine on the island Brother Aldo reads out the names of everyone who walked with him. Tobias's name is there, near the top.","heroes":["h6","h9"],"parties":["p6"],"road":"saltmarrow~veldrock","traveller":"aldo","road_rec":"r499"},{"id":"e2393","day":62,"season":3,"sday":2,"kind":"boss_race","imp":3,"text":"Word in the taverns: The Amber Sigil and Gilded Wall are both after The Kraken of the Vault. The Sunken Vault has one way down and room for one winner.","heroes":["h11","h2","h16","h9","h6"],"parties":["p3","p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e2414","day":63,"season":3,"sday":3,"kind":"meet","imp":1,"text":"Gilded Wall and The Sunlit Almanac share a fire in the Salt Cliffs. Nobody draws steel, which counts as a good meeting these days.","heroes":["h9","h6","h8","h20","h18","h19"],"parties":["p6","p4"],"loc":"saltcliffs","wx":"fog"},{"id":"e2466","day":65,"season":3,"sday":5,"kind":"delve","imp":1,"text":"Gilded Wall descends into the Sunken Vault, partly explored (36%).","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","wx":"fog"},{"id":"e2467","day":65,"season":3,"sday":5,"kind":"delve_day","imp":1,"text":"The tide-gate, the barnacled quay steps, the paymaster's quarters and 2 more: the day's work on the first floor of the Sunken Vault for Gilded Wall, taken one door at a time.","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":5,"empty":4,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2493","day":66,"season":3,"sday":6,"kind":"fight","imp":3,"text":"In the gate passage on the first floor of the Sunken Vault, Gilded Wall squares up to 3 Drowned and carries the day. The hit of the day was Gorm's Anvil Drop on the Drowned. Nobody cheered for Tobias's Ambush, but it won the fight. Loot: 12 remains, 14 trinkets, 7 barnacle oysters.","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","fight":"f148","foes":["drowned","drowned","drowned"],"where":"in the gate passage on the first floor of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-15,"wx":"fog"},{"id":"e2494","day":66,"season":3,"sday":6,"kind":"delve_day","imp":1,"text":"Seven rooms on the first floor of the Sunken Vault for Gilded Wall today: the gate passage, the gatehouse guardroom, the harbour-light stair and 4 more.","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","pace":"push","stats":{"rooms":7,"empty":6,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":1,"gear":[],"fears":1,"wild":[]},"wx":"fog"},{"id":"e2534","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"Gilded Wall spends the day on the first floor of the Sunken Vault, at a cautious pace, and covers two rooms: the assay room, the wrack line.","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","pace":"cautious","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2541","day":67,"season":3,"sday":7,"kind":"meet","imp":2,"text":"The Sunlit Almanac warns Gilded Wall about what's lurking at the mouth of the Sunken Vault. Gilded Wall pretends to already know.","heroes":["h8","h20","h18","h19","h9","h6"],"parties":["p4","p6"],"loc":"sunken_vault"},{"id":"e2572","day":68,"season":3,"sday":8,"kind":"fight","imp":3,"text":"Gilded Wall is routed by 2 Drowned and a Siren in the depositors' queue on the first floor of the Sunken Vault and runs for it. Tobias covered the retreat. Gorm has to be carried out between two of them. Injured: Gorm (concussion).","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","fight":"f155","foes":["siren","drowned","drowned"],"where":"in the depositors' queue on the first floor of the Sunken Vault","won":false,"close":true,"shape":"plain"},{"id":"e2573","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"Chalk marks on two rooms of the first floor of the Sunken Vault say Gilded Wall has been through, steadily (the drowned cistern, the depositors' queue).","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":2,"empty":1,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":1,"gear":[],"fears":1,"wild":[]}},{"id":"e2574","day":68,"season":3,"sday":8,"kind":"delve_done","imp":3,"text":"After 4 days and one bad fight, Gilded Wall climbs out, calling it a retreat with dignity. They came across the assay room and the wrack line, made it to the first floor, cleared 4 rooms, put 19% of it on paper and came away with 167 silver between them. The Sunken Vault is partly explored (43%) now, with the league's pencil marks all over it.","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","days":4,"bottom":false,"rooms":["the assay room","the wrack line"],"gold":167,"out":"Driven out","turn":"routed"},{"id":"e2575","day":68,"season":3,"sday":8,"kind":"talent","imp":2,"text":"Gorm packs Tobias's bruised ribs with a warm comfrey poultice. Tobias sleeps through the night.","heroes":["h9","h6"],"parties":["p6"],"loc":"sunken_vault","skill":"poultices"},{"id":"e2580","day":68,"season":3,"sday":8,"kind":"meet","imp":2,"text":"A scout's whistle, a quick detour: Gilded Wall leaves The Amber Sigil the road outside the Sunken Vault. Day 27 of season 2 taught them which camps to avoid.","heroes":["h9","h6","h11","h2","h16"],"parties":["p6","p3"],"loc":"sunken_vault"},{"id":"e2586","day":68,"season":3,"sday":8,"kind":"campfire","imp":1,"text":"Tobias and Gorm agree that every other party in the league is worse than this one. It is very bonding.","heroes":["h6","h9"],"parties":["p6"],"loc":"sunken_vault"},{"id":"e2623","day":70,"season":3,"sday":10,"kind":"ambush","imp":2,"text":"Two Barrel Crabs make the mistake of going for Gilded Wall on the road to Saltmarrow. The last barrel crab takes off and isn't seen again. The barrel crab had been trouble right up until Tobias' Heart Shot. Tobias's Ambush was the quiet reason it went their way. Gorm stopped to read the writing on the walls and is now worried about it. \"Everyone all right? Everyone?\" says Gorm. Loot: 4 chitin, 3 cliff crab claws.","heroes":["h9","h6"],"parties":["p6"],"loc":"saltcliffs","fight":"f159","foes":["barrel_crab","barrel_crab"],"where":"on the road to Saltmarrow","won":true,"close":false,"shape":"foe","reworded":-49,"wx":"rain"},{"id":"e2648","day":70,"season":3,"sday":10,"kind":"talent","imp":1,"text":"Tobias trades a Saltmarrow baker a sourdough starter for a sack of flour. The baker's eyes light up. Chalk it up to Trail Baker.","heroes":["h6"],"parties":["p6"],"loc":"saltmarrow","skill":"trail_baker","wx":"rain"},{"id":"e2654","day":70,"season":3,"sday":10,"kind":"campfire","imp":1,"text":"Tobias and Gorm share the last pickled onion by cutting it exactly in half, with witnesses.","heroes":["h6","h9"],"parties":["p6"],"loc":"saltmarrow","wx":"rain"},{"id":"e2661","day":71,"season":3,"sday":11,"kind":"road","imp":3,"text":"Gorm sits in on rehearsal and learns, by sitting very still, how to harmonise without being noticed.","heroes":["h9","h6"],"parties":["p6"],"road":"carrbridge~saltmarrow","traveller":"off_key","road_rec":"r560"},{"id":"e2688","day":71,"season":3,"sday":11,"kind":"ability","imp":2,"text":"On the way to Saltmarrow, Tobias reads a muddy wallow like a letter, follows it into the oaks and comes out an hour later carrying a boar shoulder.","heroes":["h6"],"parties":["p6"],"loc":"saltmarrow","skill":"back_by_supper","sk":"Back by Supper","rule":true,"wx":"rain"},{"id":"e2702","day":71,"season":3,"sday":11,"kind":"goal","imp":1,"text":"After a long night's talk, Gilded Wall settles on a goal: to finish the season as one of the top three parties.","heroes":["h9","h6"],"parties":["p6"]},{"id":"e2750","day":73,"season":3,"sday":13,"kind":"road","imp":3,"text":"A bridal party sweeps Tobias up on the road to Ironhaven and carries her for a mile of dancing. Tobias leaves at the next gate with a ribbon and a cake.","heroes":["h6","h9"],"parties":["p6"],"road":"carrbridge~ironhaven","road_rec":"r582"},{"id":"e2770","day":73,"season":3,"sday":13,"kind":"boss_race","imp":2,"text":"The Sunlit Almanac and Gilded Wall both drop out of the race for The Kraken of the Vault: The Sunlit Almanac has moved house to Carrbridge; Gilded Wall has gone hunting in Redcrag Hills. That leaves The Amber Sigil.","heroes":["h8","h20","h18","h19","h9","h6"],"parties":["p4","p6"],"loc":"sunken_vault","wx":"rain"},{"id":"e2813","day":74,"season":3,"sday":14,"kind":"talent","imp":2,"text":"Tobias lights the campfire by breathing on it. Gorm has seen this forty times and still claps. A small Fire Eater, cast without looking up.","heroes":["h6","h9"],"parties":["p6"],"loc":"redcrag","skill":"fire_eater"},{"id":"e2823","day":74,"season":3,"sday":14,"kind":"map_shared","imp":1,"text":"Maps change hands in Redcrag Hills: Gilded Wall gives The Vigil of Carrbridge a copy of what they know of the Sunken Vault, as far as the first floor.","heroes":["h9","h6","h10","h1"],"parties":["p6","p2"],"loc":"redcrag","dungeon":"sunken_vault","price":0},{"id":"e2824","day":74,"season":3,"sday":14,"kind":"meet","imp":1,"text":"Gilded Wall and The Vigil of Carrbridge share a fire in Redcrag Hills. There is a short argument about the best road to Ironhaven.","heroes":["h9","h6","h10","h1"],"parties":["p6","p2"],"loc":"redcrag"},{"id":"e2845","day":75,"season":3,"sday":15,"kind":"fight","imp":2,"text":"Gorm takes the worst of it as Gilded Wall cuts down 2 Cave Trolls and a Giant Bat in Redcrag Hills. The fight was over the moment Tobias' Thorn Whip landed on the cave troll. Inspire did more for this fight than the scoreboard shows. That was Gorm. Loot: 40 silver each, 2 troll hide, 4 troll haunches.","heroes":["h9","h6"],"parties":["p6"],"loc":"redcrag","fight":"f163","foes":["cave_troll","cave_troll","giant_bat"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e2846","day":75,"season":3,"sday":15,"kind":"fight","imp":1,"text":"In Redcrag Hills, Gilded Wall squares up to 2 Kobolds and carries the day. The last kobold is gone before anyone can stop it. Tobias' Bring It Down found the kobold from the back row. Look past the blows: Tobias's Ambush was the difference. Loot: 3 silver each.","heroes":["h9","h6"],"parties":["p6"],"loc":"redcrag","fight":"f164","foes":["kobold","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"place","reworded":-43},{"id":"e2887","day":76,"season":3,"sday":16,"kind":"hunt","imp":2,"text":"Redcrag Hills: Gorm takes half of the berries and leaves half for whatever comes next, the way the old hunters always did.","heroes":["h9","h6"],"parties":["p6"],"loc":"redcrag","wx":"rain","road_rec":"r614"},{"id":"e2927","day":77,"season":3,"sday":17,"kind":"gift","imp":2,"text":"Tobias admired Gorm's Ram's-Horn Drinking Cup one too many times. Now it's Tobias's.","heroes":["h9","h6"],"parties":["p6"],"loc":"veldrock","wx":"snow"},{"id":"e2951","day":78,"season":3,"sday":18,"kind":"boss_race","imp":3,"text":"A race for Cindervast the Hoardmother: The Amber Sigil and Gilded Wall are all bound for Emberdeep. Only one of them gets the kill.","heroes":["h11","h2","h16","h9","h6"],"parties":["p3","p6"],"loc":"emberdeep","wx":"snow"},{"id":"e2968","day":78,"season":3,"sday":18,"kind":"campfire","imp":1,"text":"Gorm tells Tobias something they've never told anyone. Tobias keeps it.","heroes":["h6","h9"],"parties":["p6"],"loc":"emberdeep","wx":"snow"},{"id":"e2976","day":79,"season":3,"sday":19,"kind":"delve","imp":1,"text":"Gilded Wall descends into Emberdeep, untouched (0%).","heroes":["h9","h6"],"parties":["p6"],"loc":"emberdeep","wx":"snow"},{"id":"e2977","day":79,"season":3,"sday":19,"kind":"delve_day","imp":1,"text":"Another day under Emberdeep: Gilded Wall walks two rooms of the first floor, at a steady pace (the cairn of the unlucky, the gate-wards).","heroes":["h9","h6"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]},"wx":"snow"},{"id":"e2978","day":79,"season":3,"sday":19,"kind":"night","imp":2,"text":"An old pilgrim stops at Gilded Wall's camp on the first floor of Emberdeep and swears there's treasure left in the Ashveil Crypts. Everyone pretends not to be interested.","heroes":["h9","h6"],"parties":["p6"],"loc":"emberdeep","wx":"snow"},{"id":"e3018","day":80,"season":3,"sday":20,"kind":"fight","imp":2,"text":"Gilded Wall makes it four wins running, dispatching 2 Salamanders in the dwarven gatehouse on the first floor of Emberdeep. The last salamander slips away while nobody is looking. The salamander took Tobias' Heart Shot full on and was never the same after. Ask the others what won it: Gorm's Inspire. Loot: 4 salamander tails.","heroes":["h9","h6"],"parties":["p6"],"loc":"emberdeep","fight":"f171","foes":["salamander","salamander"],"where":"in the dwarven gatehouse on the first floor of Emberdeep","won":true,"close":false,"shape":"streak","reworded":-58,"wx":"snow"},{"id":"e3020","day":80,"season":3,"sday":20,"kind":"fight","imp":3,"text":"Gilded Wall is routed by 3 Salamanders in the salamanders' audience pool on the first floor of Emberdeep and runs for it. Tobias was the last one out and the angriest about it. \"Lean on me,\" says Tobias. Somebody hauls Gorm out by the collar. Injured: Gorm (sprained ankle).","heroes":["h9","h6"],"parties":["p6"],"loc":"emberdeep","fight":"f172","foes":["salamander","salamander","salamander"],"where":"in the salamanders' audience pool on the first floor of Emberdeep","won":false,"close":true,"shape":"plain","wx":"snow"},{"id":"e3021","day":80,"season":3,"sday":20,"kind":"delve_day","imp":1,"text":"It's the first floor of Emberdeep today, and Gilded Wall works through it one door at a time: two rooms (the dwarven gatehouse, the salamander pools).","heroes":["h9","h6"],"parties":["p6"],"loc":"emberdeep","pace":"steady","stats":{"rooms":2,"empty":0,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":2,"close":1,"gear":[],"fears":0,"wild":[]},"wx":"snow"},{"id":"e3022","day":80,"season":3,"sday":20,"kind":"delve_done","imp":1,"text":"Emberdeep throws Gilded Wall out after 2 days, and nobody holds the door. They reached the first floor, turned up the cairn of the unlucky, cleared 3 rooms and came away with 28 silver between them.","heroes":["h9","h6"],"parties":["p6"],"loc":"emberdeep","days":2,"bottom":false,"rooms":["the cairn of the unlucky"],"gold":28,"out":"Driven out","turn":"routed","wx":"snow"},{"id":"e3023","day":80,"season":3,"sday":20,"kind":"talent","imp":2,"text":"Tobias knocks a pinecone off a branch at sixty paces to settle an argument with Gorm. Tobias puts it down to Never Misses Twice.","heroes":["h6","h9"],"parties":["p6"],"loc":"emberdeep","skill":"never_misses_twice","wx":"snow"},{"id":"e3038","day":80,"season":3,"sday":20,"kind":"meet","imp":1,"text":"Gilded Wall and The Amber Sigil make camp outside Emberdeep on opposite sides of one clearing. Each side posts a watch, and the two watches stare at each other till dawn.","heroes":["h9","h6","h11","h2","h16"],"parties":["p6","p3"],"loc":"emberdeep","wx":"snow"},{"id":"e3074","day":81,"season":3,"sday":21,"kind":"map_shared","imp":1,"text":"The Sunlit Almanac lets Gilded Wall copy the map of the Sunken Vault by the fire, every room as far as the second floor. It takes half the night and most of a candle.","heroes":["h8","h20","h18","h19","h9","h6"],"parties":["p4","p6"],"loc":"veldrock","dungeon":"sunken_vault","price":0,"wx":"snow"},{"id":"e3091","day":81,"season":3,"sday":21,"kind":"ledger","imp":2,"text":"Counters and coin this week: 17 sales, 870 silver changing hands. Biggest haul: Duren, 103 silver in Frosthold. Back up from the deep: Red Hammers (3 days in Thornmere Ruins), Gilded Wall (2 days in Emberdeep), The Oath of Frosthold (1 day in Frostspire).","heroes":["h3","h13","h9"],"parties":["p1","p6","p7"]},{"id":"e3101","day":82,"season":3,"sday":22,"kind":"road","imp":2,"text":"The Muddy Boot Pack jump from a ditch at Tobias for the first time, shout 'Boo!', and then wait politely to see if it worked.","heroes":["h6","h9"],"parties":["p6"],"road":"frosthold~veldrock","traveller":"muddy_boot","road_rec":"r662"},{"id":"e3112","day":82,"season":3,"sday":22,"kind":"boss_race","imp":2,"text":"Gilded Wall leaves Cindervast the Hoardmother to The Amber Sigil and The Sunlit Almanac: they have gone hunting in Whitepeak Pass.","heroes":["h9","h6"],"parties":["p6"],"loc":"emberdeep"},{"id":"e3113","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Tobias toasts the crew at the Frosthold tavern with a speech that leaves Gorm misty-eyed.","heroes":["h6","h9"],"parties":["p6"],"loc":"frosthold","skill":"speechmaker"},{"id":"e3122","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Gorm spots a real relic in a Frosthold junk shop, and the owner lets her have it for shifting a dresser. Relic Lore, the guild calls it.","heroes":["h9"],"parties":["p6"],"loc":"frosthold","skill":"relic_lore"},{"id":"e3153","day":83,"season":3,"sday":23,"kind":"ability","imp":2,"text":"Tobias hears rooting in the beechwood past Whitepeak Pass, strings her bow without a word, and is home before the kettle with a boar shoulder.","heroes":["h6"],"parties":["p6"],"loc":"whitepeak","skill":"back_by_supper","sk":"Back by Supper","rule":true,"wx":"storm"},{"id":"e3159","day":83,"season":3,"sday":23,"kind":"campfire","imp":1,"text":"Tobias aims an arrow at a far-off crow, misses on purpose, and gets a laugh out of Gorm.","heroes":["h6","h9"],"parties":["p6"],"loc":"whitepeak","wx":"storm"},{"id":"e3187","day":84,"season":3,"sday":24,"kind":"fight","imp":1,"text":"A Frost Wolf makes the mistake of going for Gilded Wall in Whitepeak Pass. The final blow was Tobias' Heart Shot. Loot: 3 pelts, 5 fangs & claws.","heroes":["h9","h6"],"parties":["p6"],"loc":"whitepeak","fight":"f179","foes":["frost_wolf"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"foe","reworded":-11},{"id":"e3188","day":84,"season":3,"sday":24,"kind":"hunt","imp":3,"text":"Word comes out of Whitepeak Pass with the hunters: the frost wolf is down, and Tobias and Gorm did it.","heroes":["h6","h9"],"parties":["p6"],"loc":"whitepeak"},{"id":"e3203","day":84,"season":3,"sday":24,"kind":"talent","imp":2,"text":"Gorm counts the new dents by firelight, naming them after the monsters that made them. Somebody asks how. 'Last Plate Standing,' says Gorm.","heroes":["h9"],"parties":["p6"],"loc":"whitepeak","skill":"last_plate_standing"},{"id":"e3204","day":84,"season":3,"sday":24,"kind":"campfire","imp":1,"text":"Tobias carves Gorm's initials into the campfire log. Gorm carves a rude drawing next to them. Friendship.","heroes":["h6","h9"],"parties":["p6"],"loc":"whitepeak"},{"id":"e3233","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Gorm helps a stuck cart out of the mud near Whitepeak Pass by simply leaning on it, in plate. Chalk it up to Last Plate Standing.","heroes":["h9"],"parties":["p6"],"loc":"whitepeak","skill":"last_plate_standing"},{"id":"e3238","day":85,"season":3,"sday":25,"kind":"campfire","imp":1,"text":"Moose the dog has chosen Gorm. Gorm pretends to mind. Tobias is quietly delighted.","heroes":["h6","h9"],"parties":["p6"],"loc":"whitepeak"},{"id":"e3262","day":86,"season":3,"sday":26,"kind":"fight","imp":1,"text":"Back in Whitepeak Pass, Gilded Wall dispatches a Frost Imp. Tobias closed it out with Heart Shot on the frost imp. Ambush came over Tobias at the right moment, as it does. Loot: 1 frost crystal.","heroes":["h9","h6"],"parties":["p6"],"loc":"whitepeak","fight":"f185","foes":["frost_imp"],"where":"in Whitepeak Pass","won":true,"close":false,"shape":"again","reworded":-6},{"id":"e3263","day":86,"season":3,"sday":26,"kind":"hunt","imp":2,"text":"Whitepeak Pass: Where a glacier tongue ends in a wall of blue, Tobias chips a block of ice so clear it seems to hold a light of its own. A block of glacier ice, wrapped in a wet cloth.","heroes":["h6","h9"],"parties":["p6"],"loc":"whitepeak","road_rec":"r696"},{"id":"e3420","day":90,"season":3,"sday":30,"kind":"talent","imp":2,"text":"Gorm sorts the crew's gear by who dented it, and sends each of them the bill in knuckle-taps. That's Hammer and Hold for you.","heroes":["h9"],"parties":["p6"],"loc":"whitepeak","skill":"hammer_and_hold","wx":"snow"},{"id":"e3421","day":90,"season":3,"sday":30,"kind":"campfire","imp":1,"text":"Gorm and Tobias wait out a hailstorm under one cart and play twenty questions with no winner.","heroes":["h9","h6"],"parties":["p6"],"loc":"whitepeak","wx":"snow"},{"id":"e3436","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and Gilded Wall came up short: finish the season as one of the top three parties (finished 5th).","heroes":["h9","h6"],"parties":["p6"]},{"id":"e3449","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Vigil of Carrbridge, to keep the peace: never draw first on another hero (sworn in season 2); The Amber Sigil, never to retreat (sworn in season 2); The Sunlit Almanac, to keep the peace: never draw first on another hero (sworn in season 2); The Scarlet Gallopers, that no one leaves this party (sworn in season 2); Gilded Wall, never to leave a companion behind (sworn in season 2); Verdant Edge, to share every coin (sworn in season 2); Duren, never to pay a toll (sworn in season 1). Every one of them held.","heroes":["h3"],"parties":["p2","p3","p4","p5","p6","p8"]}],"roles":{"h6":"Trail-reader","h9":"Leader · Purse-keeper"},"quest":{"what":"Delve","where":"Frostspire","why":"chasing a rumour: about 58 silver a day each, risk slight; the season goal: to finish the season as one of the top three parties; Gorm's last chance at the dream before the age ends","floor":0,"floors":4},"tactics":{"front":["h9"],"back":["h6"],"plan":"Gorm holds the front; Tobias picks off whatever gets close.","traits":{"boldness":0.0,"risk":0.01,"greed":-0.69,"sociability":-0.03,"honor":1.0,"curiosity":-0.05,"temper":-0.3,"loyalty":0.48},"mix":"1 blade, 1 bow","notes":["No healer: every wound comes home with them."],"style":["mixed"],"skills":[{"label":"Damage","skills":[{"hero":"h6","id":"game_shot","name":"Game Shot","desc":"Aims behind the shoulder, the way the old hunters taught.","tags":["hunt"],"rank":3,"uses":17},{"hero":"h9","id":"hammer_down","name":"Hammer Down","desc":"Forging technique, applied to faces.","tags":["craft"],"rank":2,"uses":9},{"hero":"h6","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":3,"uses":8},{"hero":"h6","id":"bring_it_down","name":"Bring It Down","desc":"One arrow, chosen, sent, done.","tags":["hunt"],"rank":1,"uses":8},{"hero":"h6","id":"heart_shot","name":"Heart Shot","desc":"Waited all afternoon for this one, and it shows.","tags":["hunt"],"rank":1,"uses":6},{"hero":"h9","id":"anvil_drop","name":"Anvil Drop","desc":"Brought the anvil. Nobody asked why. Now they know.","tags":["craft"],"rank":3,"uses":5},{"hero":"h9","id":"frost_brand","name":"Frost Brand","desc":"The edge rimes with ice.","tags":["ice","arcane"],"rank":1,"uses":3},{"hero":"h6","id":"quick_shot","name":"Quick Shot","desc":"Two arrows before the first lands.","tags":["hunt"],"rank":1,"uses":1}]},{"label":"Defence","skills":[{"hero":"h9","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":1,"uses":11}]},{"label":"Tricks","skills":[{"hero":"h6","id":"ambush","name":"Ambush","desc":"The party always strikes first.","tags":["stealth","nature"],"rank":1,"uses":22},{"hero":"h9","id":"hammer_and_hold","name":"Hammer and Hold","desc":"Bangs the dents out of everyone's armour without leaving the line.","tags":[],"rank":1,"uses":10},{"hero":"h6","id":"never_misses_twice","name":"Never Misses Twice","desc":"The first one was a warning.","tags":[],"rank":1,"uses":2},{"hero":"h9","id":"balanced_blade","name":"Balanced Blade","desc":"Weighted it just so. The second swing is easier than the first.","tags":["crit","craft"],"rank":1,"uses":0},{"hero":"h9","id":"last_plate_standing","name":"Last Plate Standing","desc":"Down to the last rivet and still planted.","tags":[],"rank":1,"uses":0},{"hero":"h9","id":"bolted_down","name":"Bolted Down","desc":"Bolts their boots to the floor. Figuratively. Mostly.","tags":["craft"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h9","id":"spiked_shield","name":"Spiked Shield","desc":"Bolted a few spikes on. Improved the conversation.","tags":["craft","guard"],"rank":1,"uses":0},{"hero":"h9","id":"tempered_plate","name":"Tempered Plate","desc":"Armour they quenched themselves, twice.","tags":["craft"],"rank":1,"uses":0},{"hero":"h9","id":"walking_forge","name":"Walking Forge","desc":"Plated head to toe. The plates have plates.","tags":["craft"],"rank":1,"uses":0},{"hero":"h6","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":1,"uses":0},{"hero":"h6","id":"old_woodsman","name":"Old Woodsman","desc":"Knows how every beast in the hills moves, and moves first.","tags":["hunt","nature"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h9","id":"calligrapher","name":"Calligraphy","desc":"Beautiful letters. Even on shopping lists.","tags":["craft","lore"],"rank":1,"uses":0},{"hero":"h9","id":"relic_lore","name":"Relic Lore","desc":"Knows which king owned that spoon.","tags":["trade","lore"],"rank":1,"uses":0},{"hero":"h9","id":"poultices","name":"Poultices","desc":"Mashes leaves. Wounds close.","tags":["heal","nature"],"rank":1,"uses":0},{"hero":"h9","id":"field_forge","name":"Field Forge","desc":"Sets up an anvil on any flat rock and mends what the road broke.","tags":["craft"],"rank":2,"uses":0},{"hero":"h9","id":"tavern_tales","name":"Tavern Tales","desc":"Tells a story so good people join the party.","tags":["lore"],"rank":1,"uses":0},{"hero":"h9","id":"tea_ceremony","name":"Tea Ceremony","desc":"Nothing is so bad it can't wait for the kettle.","tags":[],"rank":1,"uses":0},{"hero":"h9","id":"smith_hands","name":"Smith's Hands","desc":"Fixes and upgrades their own gear.","tags":["craft"],"rank":1,"uses":0},{"hero":"h6","id":"speechmaker","name":"Speechmaker","desc":"Has a speech. Has several.","tags":["command"],"rank":1,"uses":0},{"hero":"h6","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":1,"uses":0},{"hero":"h6","id":"tin_can_line","name":"Tin-Can Line","desc":"Cans on a string round the camp. Nothing sneaks up. Nobody sleeps.","tags":["nature","craft"],"rank":1,"uses":0},{"hero":"h6","id":"game_trails","name":"Game Trails","desc":"Knows where the deer drink, and when.","tags":["hunt","nature"],"rank":2,"uses":0},{"hero":"h6","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0},{"hero":"h6","id":"tea_ceremony","name":"Tea Ceremony","desc":"Nothing is so bad it can't wait for the kettle.","tags":[],"rank":1,"uses":0},{"hero":"h6","id":"fire_eater","name":"Fire Eater","desc":"Eats fire. Never orders hot soup.","tags":[],"rank":1,"uses":0},{"hero":"h6","id":"skinner","name":"Skinner","desc":"Has the pelt off before the crew has the kettle on.","tags":["hunt"],"rank":1,"uses":0}]}],"share":[{"hero":"h9","dmg":530,"healed":36,"taken":722,"kills":1,"row":"front"},{"hero":"h6","dmg":2842,"healed":0,"taken":0,"kills":12,"row":"back"}],"ground":{"name":"Thornmere Ruins","fights":7}},"trophies":[]};